var path = "/api/v1/payments/intents";
var payload = "{\"provider\":\"depay\",\"amount\":12000,\"currency\":\"CLP\",\"external_order_id\":\"txn_123456\",\"expires_in\":900,\"concept\":\"Compra API\",\"qr_from\":\"AR\"}";
