var canonical = string.Join("\n", "POST", path, "", Sha256Hex(payload), ts, nonce);
var signature = SignRequest(canonical, clientSecret);

using var http = new HttpClient();
using var req = new HttpRequestMessage(HttpMethod.Post, baseUrl + path);
req.Content = new StringContent(payload, Encoding.UTF8, "application/json");
req.Headers.Add("X-Client-Id", clientId);
req.Headers.Add("X-Timestamp", ts);
req.Headers.Add("X-Nonce", nonce);
req.Headers.Add("X-Signature", signature);
req.Headers.Add("Idempotency-Key", idem);
var res = await http.SendAsync(req);

